// Only honor the 🔄 button / /refresh command from the configured chat
const CHAT_ID = 'REPLACE_WITH_CHAT_ID';

const u = $json;
const cb = u.callback_query;
if (cb && cb.data === 'fgi_refresh' && String(cb.from && cb.from.id) === CHAT_ID) {
  return [{ json: { callbackId: cb.id } }];
}
const msg = u.message;
if (msg && String(msg.chat && msg.chat.id) === CHAT_ID
    && ['/refresh', '/now'].includes(String(msg.text || '').trim())) {
  return [{ json: { callbackId: '' } }];
}
return [];

// Stooq symbols for the daily snapshot (runs once regardless of input)
return [
  { json: { name: 'S&P500',  symbol: '%5Espx'  } },
  { json: { name: 'Nasdaq',  symbol: '%5Endq'  } },
  { json: { name: 'HSI',     symbol: '%5Ehsi'  } },
  { json: { name: 'Bitcoin', symbol: 'btcusd' } },
].slice(0, 4);

// Assemble the Daily Fear & Greed Update message (Telegram HTML).
// Every data source is a SINGLE http request (datacenter IPs get
// tarpitted on rapid repeat requests); every line is best-effort and
// renders "n/a" when its source failed.

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const commas = (n) => Math.round(n).toLocaleString('en-US');
const first = (name) => { try { return $(name).first().json; } catch (e) { return null; } };

// ── Fear & Greed score: CNN primary, mirror fallback ──
let score = null;
let sourceName = 'CNN';
const cnn = first('Fetch CNN');
if (cnn && cnn.fear_and_greed && typeof cnn.fear_and_greed.score === 'number') {
  score = Math.round(cnn.fear_and_greed.score);
} else {
  const mirror = first('Fetch Mirror');
  let raw = null;
  if (mirror && mirror.score != null) {
    raw = typeof mirror.score === 'number' ? mirror.score
        : (typeof mirror.score.score === 'number' ? mirror.score.score : null);
  }
  if (raw !== null) { score = Math.round(raw); sourceName = 'feargreedchart.com'; }
}
if (score === null) throw new Error('Could not fetch the Fear & Greed score from CNN or the mirror');

const label = score <= 20 ? 'Extreme Fear' : score <= 40 ? 'Fear'
            : score <= 60 ? 'Neutral' : score <= 80 ? 'Greed' : 'Extreme Greed';

// ── Day-over-day change vs the last scheduled 21:35 send ──
const sd = $getWorkflowStaticData('global');
let deltaNote = '';
if (typeof sd.lastScore === 'number') {
  const d = score - sd.lastScore;
  deltaNote = d > 0 ? ` (🟢 +${d})` : d < 0 ? ` (🔴 ${d})` : ' (⚪ 0)';
}
let fromSchedule = false;
try { fromSchedule = $('Daily Schedule').isExecuted === true; } catch (e) {}
if (fromSchedule || typeof sd.lastScore !== 'number') sd.lastScore = score;

// ── SGT timestamp ──
const sgtParts = (d, opts) => Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Singapore', hourCycle: 'h23', ...opts })
    .formatToParts(d).map(x => [x.type, x.value]));
const p = sgtParts(new Date(), { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
const sgtDate = `${p.year}-${p.month}-${p.day}`;
const sgtTime = `${p.hour}:${p.minute} SGT`;

// ── Index quotes: Stooq daily history (datacenter-friendly), with the
// mirror's own market block as automatic fallback ──
const mirrorData = first('Fetch Mirror');
const QUOTES = [
  { name: 'S&P500',  mirrorKeys: ['^GSPC', '^SPX', 'SPX', 'GSPC', 'SP500'] },
  { name: 'Nasdaq',  mirrorKeys: ['^IXIC', 'IXIC', '^NDQ', 'NDQ', 'NASDAQ', 'NDX', '^NDX'] },
  { name: 'HSI',     mirrorKeys: ['^HSI', 'HSI'] },
  { name: 'Bitcoin', mirrorKeys: ['BTC-USD', 'BTCUSD', 'BTC', 'BITCOIN'] },
];
const qResp = (() => { try { return $('Fetch Quotes').all(); } catch (e) { return []; } })();
const stooqQuote = (i) => {
  // Stooq daily CSV: Date,Open,High,Low,Close,Volume — last two closes
  const rows = String(qResp[i].json.data).split('\n').map(r => r.trim())
    .filter(r => /^\d{4}-\d{2}-\d{2},/.test(r));
  if (rows.length < 2) throw new Error('no stooq data');
  const close = (r) => parseFloat(r.split(',')[4]);
  const price = close(rows[rows.length - 1]);
  const prev = close(rows[rows.length - 2]);
  if (!isFinite(price) || !isFinite(prev) || prev === 0) throw new Error('bad stooq data');
  return { price, pct: ((price - prev) / prev) * 100 };
};
const mirrorMarket = (mirrorData && typeof mirrorData === 'object' && mirrorData.market) || {};
const mirrorKeyIndex = {};
for (const k of Object.keys(mirrorMarket)) mirrorKeyIndex[k.toUpperCase()] = mirrorMarket[k];
const mirrorQuote = (keys) => {
  for (const k of keys) {
    const e = mirrorKeyIndex[k.toUpperCase()];
    if (e && typeof e.price === 'number' && typeof e.pct === 'number') {
      return { price: e.price, pct: e.pct };
    }
  }
  throw new Error('no mirror quote');
};
const quoteLines = QUOTES.map((q, i) => {
  let quote = null;
  try { quote = stooqQuote(i); } catch (e) {}
  if (!quote) { try { quote = mirrorQuote(q.mirrorKeys); } catch (e) {} }
  if (!quote) return `  • ${q.name}: n/a`;
  const dir = quote.pct < 0
    ? `🔴 -${Math.abs(quote.pct).toFixed(1)}` : `🟢 +${quote.pct.toFixed(1)}`;
  return `  • ${q.name}: ${commas(quote.price)} (${dir}%)`;
});

// ── US monthly series: ONE combined FRED CSV (FEDFUNDS,CPIAUCSL,UNRATE) ──
const fredDate = (d) => { const [y, m, day] = d.split('-'); return `${+day}/${+m}/${y}`; };
let fredHeader = [];
let fredRows = [];
try {
  const lines = String(first('Fetch FRED').data).split('\n').map(r => r.trim()).filter(Boolean);
  fredHeader = lines[0].split(',').map(h => h.replace(/"/g, '').trim().toUpperCase());
  fredRows = lines.slice(1).map(r => r.split(',').map(c => c.replace(/"/g, '').trim()))
    .filter(c => /^\d{4}-\d{2}-\d{2}$/.test(c[0]));
} catch (e) {}
const seriesVals = (id) => {
  const col = fredHeader.indexOf(id);
  if (col < 1) return [];
  return fredRows
    .filter(c => c[col] && c[col] !== '.' && !isNaN(parseFloat(c[col])))
    .map(c => ({ d: c[0], v: parseFloat(c[col]) }));
};
const levelLine = (labelTxt, id) => {
  const rows = seriesVals(id);
  if (rows.length < 2) return `  • ${labelTxt}: n/a`;
  const cur = rows[rows.length - 1];
  const last = rows[rows.length - 2];
  return `  • ${labelTxt}: ${cur.v}% (last: ${last.v}% (as of ${fredDate(last.d)}))`;
};
const yoyLine = (labelTxt, id) => {
  const rows = seriesVals(id);
  if (rows.length < 14) return `  • ${labelTxt}: n/a`;
  const cur = ((rows[rows.length - 1].v / rows[rows.length - 13].v) - 1) * 100;
  const last = ((rows[rows.length - 2].v / rows[rows.length - 14].v) - 1) * 100;
  return `  • ${labelTxt}: ${cur.toFixed(1)}% (last: ${last.toFixed(1)}% (as of ${fredDate(rows[rows.length - 2].d)}))`;
};
const fredLines = [
  levelLine('Interest Rate', 'FEDFUNDS'),
  yoyLine('CPI', 'CPIAUCSL'),
  levelLine('Unemployment Rate', 'UNRATE'),
];

// ── Top 3 headlines with publish time in SGT (CNBC RSS) ──
let newsLines = ['      • (news unavailable)'];
try {
  const xml = String(first('Fetch News').data).replace(/[\r\n]/g, '');
  const lines = xml.split('<item>').slice(1, 4).map(part => {
    let t = (part.match(/<title>(.*?)<\/title>/) || [])[1] || '';
    t = t.replace(/<!\[CDATA\[|\]\]>/g, '')
         .replace(/&amp;/g, '&').replace(/&#039;|&apos;/g, "'").replace(/&quot;/g, '"').trim();
    if (!t) return null;
    let when = '';
    const pd = (part.match(/<pubDate>(.*?)<\/pubDate>/) || [])[1];
    if (pd) {
      const dt = new Date(pd);
      if (!isNaN(dt)) {
        const pp = sgtParts(dt, { year: 'numeric', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
        when = ` (${+pp.day}/${+pp.month}/${pp.year} ${pp.hour}:${pp.minute} SGT)`;
      }
    }
    return `      • ${t}${when}`;
  }).filter(Boolean);
  if (lines.length) newsLines = lines;
} catch (e) {}

// ── Assemble (HTML parse mode: escape data, then add tags) ──
const warn = sourceName !== 'CNN' ? ' ⚠️ mirror value, CNN unreachable' : '';
const snapshot = [...quoteLines, ...fredLines, '  • Top 3 breaking news:', ...newsLines].join('\n');

const text = [
  '<b><u>📊 Daily Fear &amp; Greed Update</u></b>',
  '',
  `📈 Fear &amp; Greed Index: ${score} (${label})${deltaNote}${esc(warn)}`,
  `📅 ${sgtDate}, ${sgtTime}`,
  '',
  '📉 Index:',
  esc(snapshot),
].join('\n');

return [{ json: { text, score, label, source: sourceName } }];
